use serde_json::{Value, from_str};
use std::collections::BTreeMap;

pub fn solve(input: Value) -> Value {
    let map: BTreeMap<i64, i64> = input.as_array()
        .unwrap()
        .iter()
        .map(|pair| {
            let pair = pair.as_array().unwrap();
            (pair[0].as_i64().unwrap(), pair[1].as_i64().unwrap())
        })
        .fold(BTreeMap::new(), |mut acc, (key, value)| {
            *acc.entry(key).or_insert(0) += value;
            acc
        });

    Value::Array(map.into_iter().map(|(key, value)| {
        Value::Array(vec![Value::Number(key.into()), Value::Number(value.into())])
    }).collect())
}
